 :root{color-scheme:dark;--bg:#090b18;--panel:#0e1122;--line:rgba(154,174,255,.13);--muted:#858ba7;--white:#f4f4ff;--cyan:#62f5e5;--pink:#ff69b4;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% 6%,#151935 0,#0a0c1a 42%,#080a15 100%);color:var(--white);font-family:var(--sans);display:flex;justify-content:center;overflow-x:hidden}.game-shell{width:min(1210px,100%);padding:0 36px;display:flex;flex-direction:column;min-height:100vh}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);flex:none}.brand{display:flex;gap:11px;align-items:center;text-decoration:none;color:#f7f6ff;font-size:15px;letter-spacing:2.5px;font-weight:700}.brand-mark{font-size:23px;color:var(--cyan);filter:drop-shadow(0 0 7px #62f5e588)}.brand-light{font-weight:400;color:#a7aac2}.edition,.panel-kicker,.hud-label,.board-footer,.page-footer,.control-row,.best-score>span,.screen-hint,.eyebrow{font-family:var(--mono);letter-spacing:1.1px}.edition{font-size:10px;color:#9298b1}.edition span{color:var(--cyan);padding:0 5px}.icon-button{width:37px;height:37px;border:1px solid var(--line);border-radius:50%;background:#101328;color:#b1bbdc;font-size:15px;cursor:pointer;transition:.2s}.icon-button:hover{border-color:var(--cyan);color:var(--cyan)}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 276px;gap:40px;align-items:stretch;padding:35px 0 23px;flex:1}.game-column{min-width:0;display:flex;flex-direction:column}.hud{display:flex;align-items:center;justify-content:space-between;height:55px;padding:0 5px 14px}.hud-stat{display:flex;flex-direction:column;gap:4px;min-width:120px}.hud-label{font-size:9px;color:#858ba7}.hud-stat strong{font-family:var(--mono);font-size:17px;font-weight:500;letter-spacing:1.4px}.hud-center{display:flex;align-items:center;gap:8px;font:10px var(--mono);letter-spacing:1.4px;color:#b9bfd7}.level-pip{width:6px;height:6px;border-radius:50%;background:var(--pink);box-shadow:0 0 10px var(--pink)}.hud-right{align-items:flex-end}.lives{color:var(--pink);font-size:14px!important;letter-spacing:4px!important}.board-wrap{position:relative;width:100%;aspect-ratio:1.6;border:1px solid rgba(133,155,255,.2);background:#0b0e1e;box-shadow:0 18px 70px #0006,inset 0 0 55px #13193855;overflow:hidden;border-radius:4px;touch-action:none}canvas{display:block;width:100%;height:100%}.board-wrap:after{content:"";position:absolute;inset:0;pointer-events:none;border:1px solid #ffffff08;background:linear-gradient(180deg,#ffffff03,transparent 30%,#00000012)}.screen{position:absolute;inset:0;z-index:2;display:grid;place-items:center;background:linear-gradient(90deg,rgba(8,10,23,.91),rgba(8,10,23,.69) 58%,rgba(8,10,23,.54));text-align:center;transition:opacity .32s,visibility .32s}.screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.screen-content{padding:10px}.orbit-icon{width:56px;height:50px;margin:0 auto 15px;position:relative}.planet{position:absolute;width:18px;height:18px;background:var(--cyan);border-radius:50%;top:16px;left:19px;box-shadow:0 0 23px #62f5e5a0}.ring{position:absolute;border:1px solid #62f5e599;width:49px;height:20px;left:4px;top:15px;border-radius:50%;transform:rotate(-25deg)}.ring-two{transform:rotate(35deg);border-color:#ff69b477}.eyebrow{font-size:9px;color:var(--cyan);letter-spacing:2px;margin:0 0 8px}h1{font-size:clamp(39px,6.2vw,70px);line-height:.83;letter-spacing:4px;margin:0;font-weight:700;text-shadow:0 0 35px #8f7aff28}h1 em{font-style:normal;color:var(--cyan)}.screen-copy{font-size:13px;line-height:1.6;color:#a6abc4;margin:16px 0 20px}.primary-button{background:var(--cyan);color:#09121b;border:0;padding:13px 18px;min-width:174px;font:700 10px var(--mono);letter-spacing:1.1px;cursor:pointer;display:inline-flex;justify-content:space-between;align-items:center;gap:17px;transition:transform .18s,box-shadow .18s}.primary-button:hover{transform:translateY(-2px);box-shadow:0 6px 25px #62f5e544}.button-arrow{font-size:15px}.screen-hint{font-size:8px;color:#858ba7;letter-spacing:.8px;margin:15px 0 0}kbd{font:9px var(--mono);display:inline-flex;align-items:center;justify-content:center;min-width:21px;height:21px;padding:0 5px;border:1px solid #343953;border-radius:3px;color:#c7cbe0;background:#13172b;box-shadow:0 2px 0 #252a44}.screen-hint kbd{height:17px;min-width:39px;font-size:8px;margin:0 3px}.pause-badge{position:absolute;z-index:3;top:15px;left:50%;transform:translateX(-50%);font:10px var(--mono);letter-spacing:1.2px;color:#f5f5ff;background:#12162cdd;border:1px solid #ffffff24;padding:9px 13px}.pause-badge span{color:var(--cyan);padding:0 4px}.pause-badge[hidden]{display:none}.board-footer{height:40px;display:flex;align-items:center;justify-content:space-between;font-size:8px;color:#7e849f;letter-spacing:.8px}.board-footer>span:first-child{display:flex;align-items:center;gap:7px}.status-dot{width:5px;height:5px;border-radius:50%;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}.footer-tip b{font-size:12px;color:var(--cyan);font-weight:400;margin-left:5px}.side-panel{padding:12px 0 0;display:flex;flex-direction:column}.panel-kicker{display:block;font-size:9px;letter-spacing:1.15px;color:#9096b0;margin-bottom:18px}.objective h2{font-size:24px;line-height:1.08;letter-spacing:-.7px;margin:0;font-weight:600}.objective h2 span{color:var(--cyan)}.objective p{font-size:12px;line-height:1.7;color:#9da3bd;margin:13px 0 22px;max-width:235px}.panel-divider{height:1px;background:var(--line);margin:0 0 23px}.controls .panel-kicker{margin-bottom:16px}.control-row{display:flex;justify-content:space-between;align-items:center;margin:0 0 13px;color:#9da3bd;font-size:8px;letter-spacing:.5px;gap:5px}.keys{display:flex;gap:4px;align-items:center}.keys small{font-size:7px;color:#656c87;padding:0 2px}.touch-note{font-size:10px;color:#747b98;margin:13px 0 22px}.powerups .panel-kicker{margin-bottom:14px}.power-row{display:flex;align-items:center;gap:12px;margin:0 0 14px}.power-icon{width:31px;height:31px;border:1px solid #62f5e544;background:#62f5e50c;color:var(--cyan);display:grid;place-items:center;font-size:17px;border-radius:4px}.slow-icon{color:var(--pink);border-color:#ff69b444;background:#ff69b40b}.power-row b,.power-row small{display:block}.power-row b{font:9px var(--mono);letter-spacing:.5px;color:#d7d9e8;margin-bottom:4px}.power-row small{font-size:9px;color:#8289a4}.best-score{margin-top:auto;border-top:1px solid var(--line);padding-top:17px;display:flex;justify-content:space-between;align-items:center}.best-score>span{font-size:8px;color:#8289a4;letter-spacing:.6px}.best-score strong{font:12px var(--mono);color:var(--cyan);letter-spacing:1px}.page-footer{height:44px;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;font-size:8px;color:#636a84;letter-spacing:.8px}.page-footer b{color:var(--cyan);padding:0 5px;font-weight:400}
@media(max-width:850px){.game-shell{padding:0 22px}.game-layout{grid-template-columns:minmax(0,1fr) 230px;gap:25px}.objective h2{font-size:21px}.control-row{font-size:7px}.keys{gap:3px}.keys kbd{min-width:18px;height:19px;font-size:8px}}
